"""Internal stream sorting helper."""
from typing import List
from event_packet import EventPacket
import hashlib

def order_packets(packets: List[EventPacket]) -> List[EventPacket]:
    """
    Orders event packets primarily by severity (descending),
    then deterministically by payload SHA-256 digest (ascending)
    for tie-breaking as per Rule H07.
    """
    def get_sort_key(p: EventPacket):
        # Calculate SHA-256 digest of the payload for deterministic tie-breaking.
        # Ensure payload is encoded to bytes before hashing.
        payload_digest = hashlib.sha256(p.payload.encode('utf-8')).hexdigest()
        return (-p.severity, payload_digest)

    return sorted(packets, key=get_sort_key)

def get_max_severity(packets: List[EventPacket]) -> int:
    return max((p.severity for p in packets), default=0)

def count_critical_packets(packets: List[EventPacket]) -> int:
    return sum(1 for p in packets if p.is_critical())
